  name: 'Text content in a table',
  render: ({
    side,
    align
  }) => {
    const rows = [{
      term: 'Justification',
      definition: 'The act of God declaring a sinner righteous on the basis of faith in Jesus Christ.'
    }, {
      term: 'Sanctification',
      definition: 'The ongoing process by which a believer is made holy and conformed to Christ.'
    }];
    return <Table className="tw:w-[420px]">
        <TableCaption>Hover the truncated definition text to read the full entry.</TableCaption>
        <TableHeader>
          <TableRow>
            <TableHead>Term</TableHead>
            <TableHead>Definition</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map(row => <TableRow key={row.term}>
              <TableCell>{row.term}</TableCell>
              <TableCell>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="tw:block tw:max-w-[220px] tw:overflow-hidden tw:text-ellipsis tw:whitespace-nowrap">
                      {row.definition}
                    </span>
                  </TooltipTrigger>
                  <TooltipContent side={side} align={align}>
                    <p className="tw:max-w-xs">{row.definition}</p>
                  </TooltipContent>
                </Tooltip>
              </TableCell>
            </TableRow>)}
        </TableBody>
      </Table>;
  },
  parameters: {
    docs: {
      description: {
        story: 'A tooltip attached to the text content inside table cells — a common pattern for revealing text that is truncated to fit the column.'
      }
    }
  }
